class Solution {
    public int findMinMoves(int[] machines) {
        int total = 0;
        for (int m : machines) total += m;
        int n = machines.length;
        if (total % n != 0) return -1;
        int avg = total / n;
        int result = 0, runningSum = 0;
        for (int m : machines) {
            runningSum += m - avg;
            result = Math.max(result, Math.max(Math.abs(runningSum), m - avg));
        }
        return result;
    }
}
